/* Erklärungen zu den Funktionsaufrufen (in class.i18n.php)
    echo _N($msgid, $plural, $n)
    z.B.: _N('agent', 'agents', $n)
    -> sucht in dieser Datei nach: 'agent(char0)agents'
        eintragen als:
        'agent' . "\0" . 'agents' => 'Agent' . "\0" . 'Agenten',

    echo _P($context, $msgid)
    echo _NP($context, $singular, $plural, $n) - bisher ungenutzt
    z.B.: _P('action-button', 'Open')
         -> sucht hier nach string: 'action-button(char004)Open')
            eintragen als:
            'action-buttonOpen' => 'Eröffnen',
            HINWEIS: original wird das Char4 als Zeichen eingetragen, und in Netbeans nicht angezeigt
            oder
            'action-button' . chr(4) . 'Open' => 'Eröffnen',
// PlusAnpassung Ende: function desc */
